/* @lc app=leetcode id=3821 lang=kotlin */ class Solution { fun nthSmallest(n: Long, k: Int): Long = Array(61) { LongArray(61) }.also { c -> (0..60).forEach { i -> (0..i).forEach { j -> c[i][j] = if (j == 0 || j == i) 1L else c[i - 1][j - 1] + c[i - 1][j] } } }.let { C -> (59 downTo 0).fold(Triple(0L, n, k)) { (res, nn, kk), b -> if (kk == 0) Triple(res, nn, kk) else (if (kk <= b) C[b][kk] else 0L).let { c -> if (nn > c) Triple(res or (1L shl b), nn - c, kk - 1) else Triple(res, nn, kk) } }.first } }